
import re
import unicodedata
from typing import Sequence, Union

from alembic import op
import sqlalchemy as sa


# Keep the revision ID generated by Alembic.
revision: str = "d33595290156"
down_revision: Union[str, Sequence[str], None] = "6b89be63bf7f"
branch_labels: Union[str, Sequence[str], None] = None
depends_on: Union[str, Sequence[str], None] = None


def generate_slug(name: str, organization_id: int, used_slugs: set[str]) -> str:
    normalized = unicodedata.normalize("NFKD", name)
    ascii_name = normalized.encode("ascii", "ignore").decode("ascii")

    base_slug = re.sub(r"[^a-z0-9]+", "-", ascii_name.lower()).strip("-")

    if not base_slug:
        base_slug = f"organization-{organization_id}"

    slug = base_slug
    counter = 2

    while slug in used_slugs:
        suffix = f"-{counter}"
        slug = f"{base_slug[:180 - len(suffix)]}{suffix}"
        counter += 1

    used_slugs.add(slug)
    return slug


def upgrade() -> None:
    # 1. Add slug as nullable to support existing records.
    op.add_column(
        "organizations",
        sa.Column("slug", sa.String(length=180), nullable=True),
    )

    # 2. Generate unique slugs for existing organizations.
    bind = op.get_bind()

    organizations = bind.execute(
        sa.text(
            "SELECT id, name FROM organizations ORDER BY id"
        )
    ).mappings().all()

    used_slugs: set[str] = set()

    for organization in organizations:
        slug = generate_slug(
            organization["name"],
            organization["id"],
            used_slugs,
        )

        bind.execute(
            sa.text(
                "UPDATE organizations SET slug = :slug WHERE id = :id"
            ),
            {
                "slug": slug,
                "id": organization["id"],
            },
        )

    # 3. Enforce uniqueness.
    op.create_unique_constraint(
        "uq_organizations_slug",
        "organizations",
        ["slug"],
    )

    # 4. Make slug mandatory.
    op.alter_column(
        "organizations",
        "slug",
        existing_type=sa.String(length=180),
        nullable=False,
    )


def downgrade() -> None:
    op.drop_constraint(
        "uq_organizations_slug",
        "organizations",
        type_="unique",
    )

    op.drop_column("organizations", "slug")
